'use strict';
// GFA — Gold False Auction Engine. Original price-behaviour research lab.
// Measures excursion outside an established range, failure to gain acceptance, then re-entry velocity.
const fs=require('fs'),R=JSON.parse(fs.readFileSync('data/xauusd-m5-dukascopy.json','utf8'));
const M=R.map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t),N=M.length,C=Math.floor(N*.75);
function atr(){let z=Array(N).fill(NaN);for(let i=14;i<N;i++){let s=0;for(let j=i-13;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));z[i]=s/14}return z}const A=atr();
function signal(i,q){if(i<q.look+q.out+20||!A[i])return;let a=i-q.out-q.look,b=i-q.out-1,hi=-Infinity,lo=Infinity;for(let j=a;j<=b;j++){hi=Math.max(hi,M[j].h);lo=Math.min(lo,M[j].l)}let outsideUp=0,outsideDn=0,maxUp=0,maxDn=0;for(let j=i-q.out;j<i;j++){if(M[j].c>hi)outsideUp++;if(M[j].c<lo)outsideDn++;maxUp=Math.max(maxUp,M[j].h-hi);maxDn=Math.max(maxDn,lo-M[j].l)}let x=M[i],rg=x.h-x.l;if(!(rg>0))return;let vel=Math.abs(x.c-M[i-1].c)/A[i],cpB=(x.c-x.l)/rg,cpS=(x.h-x.c)/rg;
// Failed downside auction -> BUY: meaningful excursion, little close acceptance outside, then decisive re-entry.
if(maxDn/A[i]>=q.depth&&outsideDn<=q.accept&&x.c>lo&&x.c>x.o&&cpB>=q.cp&&vel>=q.vel)return'BUY';
// Failed upside auction -> SELL.
if(maxUp/A[i]>=q.depth&&outsideUp<=q.accept&&x.c<hi&&x.c<x.o&&cpS>=q.cp&&vel>=q.vel)return'SELL'}
function run(q,L,H){let T=[],o=null;for(let i=Math.max(100,L);i<Math.min(H,N-1);i++){if(o){let x=M[i],p=null;if(o.s==='BUY'){if(x.l<=o.sl)p=o.sl;else if(x.h>=o.tp)p=o.tp}else{if(x.h>=o.sl)p=o.sl;else if(x.l<=o.tp)p=o.tp}if(p==null&&i-o.e+1>=q.hold)p=x.c;if(p!=null){T.push(o.s==='BUY'?(p-o.en)/(o.en-o.sl):(o.en-p)/(o.sl-o.en));o=null}continue}let s=signal(i,q);if(!s)continue;let en=M[i+1].o,r=q.sl*A[i];o={s,en,sl:s==='BUY'?en-r:en+r,tp:s==='BUY'?en+q.rr*r:en-q.rr*r,e:i+1}}return T}function st(T){let w=0,g=0,l=0,e=0,p=0,d=0;for(let r of T){e+=r;if(r>0){w++;g+=r}else l-=r;p=Math.max(p,e);d=Math.max(d,p-e)}return{n:T.length,wr:T.length?100*w/T.length:0,pf:l?g/l:g?99:0,net:e,dd:d}}
let Q=[];for(let look of [12,20])for(let out of [2,3])for(let depth of [.25,.45,.65])for(let accept of [0,1])for(let cp of [.6,.72])for(let vel of [.15,.3])for(let rr of [1,1.5])Q.push({look,out,depth,accept,cp,vel,rr,sl:1,hold:10});console.log(`GFA FAST LAB | configs=${Q.length} | M5=${N} | DEV75/HOLD25`);let X=Q.map(q=>({q,d:st(run(q,0,C))})).filter(x=>x.d.n>=40).sort((a,b)=>(b.d.net-a.d.net));console.log('\nTOP 25 DEV → UNTOUCHED HOLD');X.slice(0,25).forEach((x,k)=>{let h=st(run(x.q,C,N));console.log(`${k+1} ${JSON.stringify(x.q)} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net>=0?'+':''}${x.d.net.toFixed(2)} DD${x.d.dd.toFixed(2)} | HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.net>=0?'+':''}${h.net.toFixed(2)} DD${h.dd.toFixed(2)}`)});console.log('\nROBUST CANDIDATES: DEV PF>=1.25 NET>0, HOLD PF>=1.25 NET>0');let Z=X.map(x=>({x,h:st(run(x.q,C,N))})).filter(z=>z.x.d.pf>=1.25&&z.x.d.net>0&&z.h.n>=15&&z.h.pf>=1.25&&z.h.net>0);if(!Z.length)console.log('NONE — reject GFA v1, redesign rather than overfit.');else Z.slice(0,15).forEach((z,k)=>console.log(`${k+1} ${JSON.stringify(z.x.q)} | DEV T${z.x.d.n} WR${z.x.d.wr.toFixed(1)} PF${z.x.d.pf.toFixed(2)} N${z.x.d.net.toFixed(2)} | HOLD T${z.h.n} WR${z.h.wr.toFixed(1)} PF${z.h.pf.toFixed(2)} N${z.h.net.toFixed(2)}`));